{"code":"import math


def layout(packet):
    spec = packet['spec']
    assets = spec['assets']
    width, depth = packet['width'], packet['depth']
    fixed = list(packet['fixed'])
    fixed_by_id = {o['id']: o for o in fixed}
    required = {o['id']: o['asset'] for o in spec['required_objects']}
    constraints = spec.get('constraints', [])
    regions = {r['id']: r for r in spec.get('regions', [])}
    fronts = [c for c in constraints if c['type'] == 'in_front_of']
    references = {c['reference'] for c in fronts}
    wall_rules = {}
    forbidden = []
    for c in constraints:
        if c['type'] == 'near_wall':
            wall_rules.setdefault(c['subject'], []).append(c)
        elif c['type'] == 'keep_clear':
            r = regions[c['region']]
            forbidden.append((r['x'], r['y'], r['x'] + r['width'], r['y'] + r['depth']))

    def rectangle(o):
        a = assets[o['asset']]
        w, d = a['width'], a['depth']
        if o['yaw_deg'] % 180:
            w, d = d, w
        return (o['x'] - w / 2, o['y'] - d / 2,
                o['x'] + w / 2, o['y'] + d / 2)

    def overlaps(a, b):
        return (min(a[2], b[2]) - max(a[0], b[0]) > 1e-8 and
                min(a[3], b[3]) - max(a[1], b[1]) > 1e-8)

    def front_ok(c, subject, sr, reference, rr):
        yaw = reference['yaw_deg'] % 360
        fx, fy = ((0, 1), (-1, 0), (0, -1), (1, 0))[int(yaw // 90)]
        dx = subject['x'] - reference['x']
        dy = subject['y'] - reference['y']
        sw, sd = sr[2] - sr[0], sr[3] - sr[1]
        rw, rd = rr[2] - rr[0], rr[3] - rr[1]
        gap = dx * fx + dy * fy - (abs(fx) * (sw + rw) + abs(fy) * (sd + rd)) / 2
        lateral = abs(dx * fy - dy * fx)
        extent = (abs(fy) * (sw + rw) + abs(fx) * (sd + rd)) / 2
        return -1e-8 <= gap <= c['max_gap'] + 1e-8 and lateral <= extent + 1e-8

    fixed_rects = [rectangle(o) for o in fixed]
    fixed_rect_by_id = {o['id']: r for o, r in zip(fixed, fixed_rects)}
    names = sorted(name for name in required if name not in fixed_by_id)
    poses, rects = [], []
    for name in names:
        pp, rr, seen = [], [], set()
        for o in packet['domains'].get(name, []):
            if o['id'] != name or o['asset'] != required[name]:
                continue
            r = rectangle(o)
            if r[0] < -1e-8 or r[1] < -1e-8 or r[2] > width + 1e-8 or r[3] > depth + 1e-8:
                continue
            if any(overlaps(r, z) for z in forbidden) or any(overlaps(r, z) for z in fixed_rects):
                continue
            good = True
            for c in wall_rules.get(name, []):
                gap = {'north': depth - r[3], 'south': r[1],
                       'east': width - r[2], 'west': r[0]}[c['wall']]
                if not -1e-8 <= gap <= c['max_gap'] + 1e-8:
                    good = False
                    break
            if not good:
                continue
            for c in fronts:
                if c['subject'] == name and c['reference'] in fixed_by_id:
                    ref = c['reference']
                    if not front_ok(c, o, r, fixed_by_id[ref], fixed_rect_by_id[ref]):
                        good = False
                        break
                elif c['reference'] == name and c['subject'] in fixed_by_id:
                    sub = c['subject']
                    if not front_ok(c, fixed_by_id[sub], fixed_rect_by_id[sub], o, r):
                        good = False
                        break
            key = (r, o['yaw_deg'] % 360 if name in references else 0)
            if good and key not in seen:
                seen.add(key)
                pp.append(o)
                rr.append(r)
        poses.append(pp)
        rects.append(rr)

    nw, nh = int(width), int(depth)
    cells = nw * nh
    full = (1 << cells) - 1
    left = sum(1 << (y * nw) for y in range(nh))
    right = left << (nw - 1)
    no_left, no_right = full ^ left, full ^ right
    sx, sy = packet['start']
    gx, gy = packet['goal']
    start = 1 << (sy * nw + sx)
    goal = 1 << (gy * nw + gx)
    endpoints = start | goal
    minimum = packet['minimum_steps']

    def cell_mask(r):
        xs = [x for x in range(nw) if r[0] - .15 < x + .5 < r[2] + .15]
        ys = [y for y in range(nh) if r[1] - .15 < y + .5 < r[3] + .15]
        row = sum(1 << x for x in xs)
        result = 0
        for y in ys:
            result |= row << (y * nw)
        return result

    fixed_mask = 0
    for r in fixed_rects:
        fixed_mask |= cell_mask(r)
    masks = []
    for i in range(len(names)):
        pp, rr, mm = [], [], []
        for o, r in zip(poses[i], rects[i]):
            m = cell_mask(r)
            if not m & endpoints:
                pp.append(o)
                rr.append(r)
                mm.append(m)
        poses[i], rects[i] = pp, rr
        masks.append(mm)
    n = len(names)
    initial = [(1 << len(p)) - 1 for p in poses]

    def walk(blocked, want_path=False):
        if blocked & endpoints:
            return -1, 0
        free = full & ~blocked
        reached = start
        fringe = start
        layers = [start] if want_path else []
        distance = 0
        while fringe:
            if fringe & goal:
                path = 0
                if want_path and distance < minimum:
                    cursor = goal
                    path = cursor
                    for k in range(distance - 1, -1, -1):
                        adjacent = (((cursor & no_right) << 1) | ((cursor & no_left) >> 1) |
                                    (cursor << nw) | (cursor >> nw))
                        choices = adjacent & layers[k]
                        cursor = choices & -choices
                        path |= cursor
                return distance, path
            fringe = ((((fringe & no_right) << 1) | ((fringe & no_left) >> 1) |
                       (fringe << nw) | (fringe >> nw)) & free & ~reached)
            reached |= fringe
            distance += 1
            if want_path:
                layers.append(fringe)
        return -1, 0

    pair_rules = {}
    position = {name: i for i, name in enumerate(names)}
    degree = [0] * n
    for c in fronts:
        if c['subject'] in position and c['reference'] in position:
            i, j = position[c['subject']], position[c['reference']]
            pair_rules.setdefault((min(i, j), max(i, j)), []).append(c)
            degree[i] += 1
            degree[j] += 1
    compat = [[None for j in range(n)] for i in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            forward = [0] * len(poses[i])
            backward = [0] * len(poses[j])
            rules = pair_rules.get((i, j), [])
            for a, ra in enumerate(rects[i]):
                for b, rb in enumerate(rects[j]):
                    if overlaps(ra, rb):
                        continue
                    good = True
                    for c in rules:
                        if c['subject'] == names[i]:
                            good = front_ok(c, poses[i][a], ra, poses[j][b], rb)
                        else:
                            good = front_ok(c, poses[j][b], rb, poses[i][a], ra)
                        if not good:
                            break
                    if good:
                        forward[a] |= 1 << b
                        backward[b] |= 1 << a
            compat[i][j], compat[j][i] = forward, backward

    clauses = []
    clause_paths = set()
    aggregate_cache = [{} for i in range(n)]
    budget = [0]
    best = [None, -2]
    access_specs = spec.get('access_paths', [])
    fine_data = {}

    def fine_setup(clearance):
        if clearance in fine_data:
            return fine_data[clearance]
        fw = int(math.floor(width * 10 + 1e-8)) + 1
        fh = int(math.floor(depth * 10 + 1e-8)) + 1
        ff = (1 << (fw * fh)) - 1
        fl = sum(1 << (y * fw) for y in range(fh))
        fr = fl << (fw - 1)
        xl = max(0, int(math.ceil(clearance * 10 - 1e-8)))
        xr = min(fw - 1, int(math.floor((width - clearance) * 10 + 1e-8)))
        yl = max(0, int(math.ceil(clearance * 10 - 1e-8)))
        yr = min(fh - 1, int(math.floor((depth - clearance) * 10 + 1e-8)))
        room = 0
        if xr >= xl and yr >= yl:
            row = ((1 << (xr - xl + 1)) - 1) << xl
            for y in range(yl, yr + 1):
                room |= row << (y * fw)

        def blocked_rect(r):
            lo_x = max(0, int(math.ceil((r[0] - clearance) * 10 - 1e-8)))
            hi_x = min(fw - 1, int(math.floor((r[2] + clearance) * 10 + 1e-8)))
            lo_y = max(0, int(math.ceil((r[1] - clearance) * 10 - 1e-8)))
            hi_y = min(fh - 1, int(math.floor((r[3] + clearance) * 10 + 1e-8)))
            result = 0
            if hi_x >= lo_x and hi_y >= lo_y:
                row = ((1 << (hi_x - lo_x + 1)) - 1) << lo_x
                for y in range(lo_y, hi_y + 1):
                    result |= row << (y * fw)
            return result

        fm = 0
        for r in fixed_rects:
            fm |= blocked_rect(r)
        pm = [[blocked_rect(r) for r in rs] for rs in rects]
        data = (fw, fh, ff ^ fl, ff ^ fr, room, fm, pm)
        fine_data[clearance] = data
        return data

    def access_ok(chosen):
        if not access_specs:
            return True
        selected = dict(fixed_by_id)
        for i, a in enumerate(chosen):
            selected[names[i]] = poses[i][a]
        for access in access_specs:
            clearance = access.get('clearance', .15)
            fw, fh, fnl, fnr, room, blocked, pm = fine_setup(clearance)
            for i, a in enumerate(chosen):
                blocked |= pm[i][a]
            free = room & ~blocked
            region = regions[access['from_region']]
            cx = region['x'] + region['width'] / 2
            cy = region['y'] + region['depth'] / 2
            ix, iy = int(cx * 10 + .5), int(cy * 10 + .5)
            if ix < 0 or iy < 0 or ix >= fw or iy >= fh:
                return False
            fringe = (1 << (iy * fw + ix)) & free
            if not fringe:
                return False
            obj = selected[access['to_object']]
            distance = access.get('interaction_distance', .8)
            target = 0
            lo_x = max(0, int(math.ceil((obj['x'] - distance) * 10)))
            hi_x = min(fw - 1, int(math.floor((obj['x'] + distance) * 10)))
            lo_y = max(0, int(math.ceil((obj['y'] - distance) * 10)))
            hi_y = min(fh - 1, int(math.floor((obj['y'] + distance) * 10)))
            for y in range(lo_y, hi_y + 1):
                row = 0
                for x in range(lo_x, hi_x + 1):
                    if (x / 10 - obj['x']) ** 2 + (y / 10 - obj['y']) ** 2 <= distance ** 2 + 1e-10:
                        row |= 1 << x
                target |= row << (y * fw)
            target &= free
            if not target:
                return False
            seen = fringe
            while fringe and not fringe & target:
                fringe = ((((fringe & fnr) << 1) | ((fringe & fnl) >> 1) |
                           (fringe << fw) | (fringe >> fw)) & free & ~seen)
                seen |= fringe
            if not fringe:
                return False
        return True

    def propagate(ds, changed):
        queue = list(changed)
        queued = set(queue)
        while True:
            while queue:
                j = queue.pop()
                queued.discard(j)
                if not ds[j]:
                    return False
                for i in range(n):
                    if i == j:
                        continue
                    old = ds[i]
                    remaining = old
                    kept = 0
                    table = compat[i][j]
                    while remaining:
                        bit = remaining & -remaining
                        remaining -= bit
                        if table[bit.bit_length() - 1] & ds[j]:
                            kept |= bit
                    if kept != old:
                        if not kept:
                            return False
                        ds[i] = kept
                        if i not in queued:
                            queue.append(i)
                            queued.add(i)
            altered = False
            for clause in clauses:
                owner = -1
                satisfied = False
                for i, hits in enumerate(clause):
                    hit = hits & ds[i]
                    if hit:
                        if hit == ds[i]:
                            satisfied = True
                            break
                        if owner == -1:
                            owner = i
                        else:
                            owner = -2
                if satisfied or owner == -2:
                    continue
                if owner == -1:
                    return False
                new = ds[owner] & clause[owner]
                if new != ds[owner]:
                    ds[owner] = new
                    queue.append(owner)
                    queued.add(owner)
                    altered = True
            if not altered:
                return True

    def aggregate(i, domain):
        cache = aggregate_cache[i]
        if domain in cache:
            return cache[domain]
        intersection = full
        union = 0
        bits = domain
        while bits:
            bit = bits & -bits
            bits -= bit
            m = masks[i][bit.bit_length() - 1]
            intersection &= m
            union |= m
        result = (intersection, union)
        if len(cache) < 2048:
            cache[domain] = result
        return result

    def learn(path):
        if not path or path in clause_paths:
            return
        hits = []
        for mm in masks:
            value = 0
            for a, m in enumerate(mm):
                if m & path:
                    value |= 1 << a
            hits.append(value)
        if len(clauses) < 96:
            clauses.append(hits)
            clause_paths.add(path)

    def search(ds, changed):
        budget[0] += 1
        if budget[0] > 24000:
            return None
        if not propagate(ds, changed):
            return None
        while True:
            forced, possible = fixed_mask, fixed_mask
            for i, domain in enumerate(ds):
                intersection, union = aggregate(i, domain)
                forced |= intersection
                possible |= union
            distance, path = walk(forced, True)
            if distance < 0:
                return None
            unresolved = [i for i in range(n) if ds[i] & (ds[i] - 1)]
            if not unresolved:
                chosen = [d.bit_length() - 1 for d in ds]
                if distance >= minimum:
                    if access_ok(chosen):
                        return chosen
                elif distance > best[1] and access_ok(chosen):
                    best[0], best[1] = chosen, distance
                learn(path)
                return None
            if distance < minimum:
                upper_distance, unused = walk(possible)
                if 0 <= upper_distance < minimum:
                    return None
                learn(path)
                blockers = []
                for i in unresolved:
                    hit = 0
                    bits = ds[i]
                    while bits:
                        bit = bits & -bits
                        bits -= bit
                        if masks[i][bit.bit_length() - 1] & path:
                            hit |= bit
                    if hit:
                        blockers.append((i, hit))
                if not blockers:
                    return None
                if len(blockers) == 1:
                    i, hit = blockers[0]
                    if hit != ds[i]:
                        ds[i] = hit
                        if not propagate(ds, [i]):
                            return None
                        continue
            break
        i = min(unresolved, key=lambda j: (ds[j].bit_count(), -degree[j],
                    -sum(1 for a in range(len(masks[j])) if ds[j] & (1 << a) and masks[j][a] & path)))
        choices = []
        bits = ds[i]
        while bits:
            bit = bits & -bits
            bits -= bit
            a = bit.bit_length() - 1
            m = masks[i][a]
            if path:
                score = ((m & path).bit_count(), (m & ~forced).bit_count())
            else:
                score = (0, -(m & ~forced).bit_count())
            choices.append((score, a))
